def fortune_lookup(n):
    # Create a lookup table for each place value
    dfs = [1, 5, 3, 7, 11, 17, 23, 55, 89, -1]
    # Double the inversions count
    inversions = 0
    for i in range(10):
        if n >= dfs[i]:
