            n -= dfs[i]
        else:
            inversions += n // dfs[i]
            return inversions + n % dfs[i]

def max_sum_of_fortune(n, F):
    """Return the maximum sum of fortune for all numbers equaling n."""
    fortune = [inf for _ in F]
    for f in F:
        fortune[f] = 0
    for s in F:
        for c in range(s, 999999 + 1):
            fortune[ceil(c / 10)] = min(fortune[ceil(c / 10)] + long(fortune_lookup(s / 10) + (c - s) / (10 * s)), fortune_lookup(s))
    return max(fortune)

