def find_knight_placements(n):
    import random

    def is_attacked(cell1, cell2):
        for i in range(cell1[0] - 1, cell1[0] + 2):
            for j in range(cell1[1] - 1, cell1[1] + 2):
                if (i, j) != cell2 and (i, j) != cell1:
                    if cell1 in {(i, j), (i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)}:
                        return True
        return False

    def solve(n):
        solutions = []
        visited = [[False] * 1001 for _ in range(1001)]
        coordinates = [(x, y) for y in range(1001) for x in range(1001) if visited[y][x] == False]

        while coordinates:
            current = random.choice(coordinates)
            coordinates.remove(current)
            if is_attacked(current, (1, 1)):
                solutions.append(current)
                visited[current[1]][current[0]] = True
                if is_attacked((1, 1), current):
                    coordinates.remove((1, 1))
                    coordinates.remove(current)
            elif len(solutions) >= (n ** 2) // 10:
                break

        return solutions

    return solve(n)

