def calculate_sum_of_fortune(n, fortune_values):
    fortune_sum = 0
    place_values = [10**i for i in range(6, -1, -1)]  # Initialize place values from 100000 to 10
    for place_value in place_values:
        for d in range(10):  # Handle digits 1-9
            if n // place_value != 0:
                fortune_sum += ((d + 1) * max(n // place_value, 1)) * fortune_values[d]
