                new_distances = distances[node_from].copy()
                new_path = map(lambda d: (d[1], d[0] + edge_weight), new_path)
                distances[node_to][node] = 0 if node in graph[node_to] else (0, edge_weight)
                distances[node_from][node_to] = min(distances[node_from][node_to], new_distances[node])
                distances[node_to] = new_distances
                graph[node_to][node] = edge_weight
                graph[node][node_to] = edge_weight
                heapq.heapify(weights)
                heapq.heapify(new_graph[node])

        if max(new_graph[node][node] for node in new_graph) >= time + 1:
            min_time = min(min_time, time)
            max_time = max(max_time, distance[node][node])

    return (min_time, max_time)
