        graph[v].append(u)
    return graph

def find_shortest_path(graph, current, target, max_time):
    distances = {v: float('inf') for v in graph}
    distances[current] = 0
    queue = [(0, current)]
    while queue:
        current_distance, current = queue.pop(0)
        if current_distance > max_time:
            break
        for neighbor in graph[current]:
            if distances[neighbor] > current_distance + 1:
                distances[neighbor] = current_distance + 1
                queue.append((current_distance + 1, neighbor))
    return distances

def calculate_path_order(graph, n, max_time):
    k = 0
    while True:
        all_visited = True
        current_time = 0
        path = []
        path.append((1, 0))
        position = {
            1: None
        }
        for _ in range(n):
            for position_to_check in position:
                if position_to_check == None:
                    for neighbor in graph[position_to_check]:
                        if neighbor not in position:
                            position[neighbor] = position_to_check
                            break
                if position.position_to_check in graph:
                    for neighbor in graph[position_to_check]:
                        if neighbor not in path:
                            position[neighbor] = position_to_check
                            break
            current_time += 1
            distance = find_shortest_path(graph, position[position_to_check], position[position_to_check + 1], max_time)
            for node in distance:
                if node not in path:
                    if len(path) == 1 or (distance[node] > max_time and position_to_check != 0):
                        current_time -= 1
                    else:
                        all_visited = False
                        break
                if node == position_to_check:
                    break
            path.append((node + 1, current_time))
            position_to_check = position[node + 1]
        if all_visited:
            break
        k += 1
    return k, path

