from collections import defaultdict

def find_minimum_time(customers, max_machines, initial_machine_times, rental_price):
    # Initialize the solution and the server sets
    total_cost = 0
    last_time = 0
    server_sets = defaultdict(set)

    # Process each customer's requirements
    for customer in customers:
        available_machines = []
        for i in range(1, max_machines + 1):
            for time in range(1, 2501):
                if i not in initial_machine_times[customer]:
                    available_machines.append((i, time))

        # Sort machines by time used for the second copy before the first
        available_machines.sort(key=lambda x: min(x[1], available_machines.index(x)))

        # Try renting each machine
        rented_time = 0
        for i, time in available_machines:
            if time >= available_machines.index(i):
                rented_time += max((time - last_time) // 2, 1)
                last_time = time
                server_sets[i].add(0)

            else:
                break

        # Cover the time period with machines in the set
        for lead_machines in server_sets.values():
            if len(lead_machines) == 0:
                continue

            for add_machines in server_sets.values():
                if len(add_machines) == 0:
                    continue

                if lead_machines & add_machines:
                    lead_machines.difference_update(add_machines)
                else:
                    for time in range(1, min(lead_machines, add_machines)):
                        if rented_time + add_machines & time > total_cost:
                            total_cost += add_machines & time
                            break
                        add_machines.add(time)

    return min(total_cost, max_machines * (2501 // 2))
