from heapq import heapify, heappop

def max_buildings_demolished():
    n, m = map(int, input().split())
    a = list(map(int, input().split()))
    b = list(map(int, input().split()))
    p = list(map(int, input().split()))

    dp = [a[0]] + [None] * (n - 1)
    for i, acc in enumerate(dp):
        if acc is None:
            dp[i + 1] = min(acc, b[i]) if i != n - 1 else min(acc, b[i - 1], b[i])

    heap = [(-dp[0], 0)]
    for i in range(1, n + 1):
        patheff = []
        for cost in heap:
            if dp[i] <= cost[0]:
                heappop(heap)
            if cost[1] < m:
                heappush(heap, (cost[0] + p[cost[1]], cost[1] + 1))
                heappush(patheff, (cost[1] + 1, cost[0] + p[cost[1]]))
        dp[i] = -min(patheff)[0]
        if patheff:
            dp[i] = min(patheff)

    return -min(dp)

print(max_buildings_demolished())
