from math import gcd
from fractions import Fraction

def find_min_operations(n, k):
    cells = {}
    for ri, ci in cells_iter(n):
        cells[(ri, ci)] = (ri, ci, 1)

    ops = []
    for ri in range(1, n):
        for ci in range(1, ri + 1):
            cell = (ri, ci)
            if cell not in cells:
                continue
            diff, ref = cells[cell]
            closest_ref = (ri - diff, ci)
            for row in range(ri, ref):
                r, c = closest_ref
                if ref - row % (ref - r) > ref - n:
                    op = (2, ref, row - ref, 1)
                    ops.append(op)
                    break
            else:
                op = (2, ref, ri - ref, 1)
                ops.append(op)

    return len(ops) + k + 1

def cells_iter(n):
    row = 1
    ri, ci = 1, 1
    while ri <= n:
        ri = row
        ci = 1
        while ri != n:
            yield (ri, ci)
            ci += 1
        row += 1

# Example 1
print(find_min_operations(4, 5))
