from collections import defaultdict

def calculateVariants(words):
    n = len(words)
    dp = [1] * (10**6 + 1)
    for i in range(1, n):
        for j in range(i):
            if words[i].find(words[j]) == 0:
                dp[i] += dp[j]
                dp[i] %= (10**9 + 7)
    return dp[n-1]

def main():
    n = int(input().strip())
    words = [input().strip() for _ in range(n)]
    variants = calculateVariants(words)
    print(variants)

